// Where the user's data goes, computed from the current settings. Drives the DataFlowBadge.
import { hostOf, isLocalUrl } from "../adapters/llm/openaiCompat";

export type FlowLevel = "green" | "yellow" | "red";

export interface FlowInput {
  llmBaseUrl: string;
  tts: "kokoro-web" | "elevenlabs";
  /** Photos are stored and the image setting is not "No": they may be sent to the model. */
  photosMaySend: boolean;
  photoCount: number;
  hasNotes: boolean;
}

export interface FlowRow {
  what: string;
  where: string;
  /** true when this leaves the computer */
  leaves: boolean;
}

export interface Flow {
  level: FlowLevel;
  emoji: string;
  headline: string;
  rows: FlowRow[];
}

export function dataFlow(i: FlowInput): Flow {
  const host = hostOf(i.llmBaseUrl);
  const llmLocal = isLocalUrl(i.llmBaseUrl);
  const eleven = i.tts === "elevenlabs";
  const photosSent = i.photoCount > 0 && i.photosMaySend;

  let level: FlowLevel;
  let headline: string;
  if (!llmLocal && photosSent) {
    level = "red";
    headline = `Photos are sent to ${host}`;
  } else if (eleven && llmLocal) {
    level = "yellow";
    headline = "Story text → ElevenLabs. Photos stay on this device.";
  } else if (eleven) {
    level = "yellow";
    headline = `Notes → ${host}; story text → ElevenLabs.`;
  } else if (!llmLocal) {
    level = "yellow";
    headline = `Notes and prompts are sent to ${host}.`;
  } else {
    level = "green";
    headline = "Fully local";
  }

  const rows: FlowRow[] = [];
  if (i.photoCount > 0) {
    rows.push(
      photosSent
        ? { what: "Your photos (downscaled, no EXIF)", where: llmLocal ? `Your local model (${host})` : host, leaves: !llmLocal }
        : { what: "Your photos", where: "Stay in this browser; not sent anywhere", leaves: false },
    );
  }
  if (i.hasNotes) rows.push({ what: "Your notes", where: llmLocal ? `Your local model (${host})` : host, leaves: !llmLocal });
  rows.push({ what: "The story prompt and the story the model writes", where: llmLocal ? `Your local model (${host})` : host, leaves: !llmLocal });
  rows.push(
    eleven
      ? { what: "Story text, to be spoken", where: "ElevenLabs (api.elevenlabs.io)", leaves: true }
      : { what: "Story text, to be spoken", where: "Kokoro, running in this browser", leaves: false },
  );
  rows.push({ what: "API keys", where: "Saved in this browser; sent only to the service they belong to", leaves: false });
  rows.push({ what: "Anything else", where: "Nothing. There is no server of ours to send it to.", leaves: false });

  return { level, emoji: { green: "🟢", yellow: "🟡", red: "🔴" }[level], headline, rows };
}

import { useState } from "react";
import type { Flow } from "./dataFlow";

/** Top-bar privacy badge. Click for a table of what goes where. */
export function DataFlowBadge({ flow }: { flow: Flow }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="flow">
      <button className="badge-button" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        <span aria-hidden>{flow.emoji}</span> {flow.headline}
      </button>
      {open && (
        <div className="flow-panel" role="dialog" aria-label="Where your data goes">
          <table>
            <thead>
              <tr>
                <th>What</th>
                <th>Goes to</th>
              </tr>
            </thead>
            <tbody>
              {flow.rows.map((r) => (
                <tr key={r.what} className={r.leaves ? "leaves" : ""}>
                  <td>{r.what}</td>
                  <td>
                    {r.leaves ? "⚠ " : ""}
                    {r.where}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { describe, expect, it } from "vitest";
import { dataFlow, type FlowInput } from "./dataFlow";

const base: FlowInput = {
  llmBaseUrl: "http://localhost:11434/v1",
  tts: "kokoro-web",
  photosMaySend: true,
  photoCount: 2,
  hasNotes: true,
};

describe("dataFlow", () => {
  it("green: local model and offline voice, even with photos", () => {
    const f = dataFlow(base);
    expect(f.level).toBe("green");
    expect(f.headline).toBe("Fully local");
    expect(f.rows.find((r) => r.what.startsWith("Your photos"))?.leaves).toBe(false);
  });

  it("yellow: local model, ElevenLabs voice; photos stay on the device", () => {
    const f = dataFlow({ ...base, tts: "elevenlabs" });
    expect(f.level).toBe("yellow");
    expect(f.headline).toBe("Story text → ElevenLabs. Photos stay on this device.");
    expect(f.rows.some((r) => r.where.includes("ElevenLabs") && r.leaves)).toBe(true);
  });

  it("red: remote model and photos, naming the host", () => {
    const f = dataFlow({ ...base, llmBaseUrl: "https://api.example.com/v1" });
    expect(f.level).toBe("red");
    expect(f.headline).toBe("Photos are sent to api.example.com");
    expect(f.rows.find((r) => r.what.startsWith("Your photos"))).toMatchObject({ where: "api.example.com", leaves: true });
  });

  it("remote model with no photos (or photos turned off) is yellow, not red", () => {
    const remote = { ...base, llmBaseUrl: "https://api.example.com/v1" };
    expect(dataFlow({ ...remote, photoCount: 0 }).level).toBe("yellow");
    const off = dataFlow({ ...remote, photosMaySend: false });
    expect(off.level).toBe("yellow");
    expect(off.rows.find((r) => r.what === "Your photos")?.leaves).toBe(false);
  });

  it("remote model plus ElevenLabs without photos names both", () => {
    const f = dataFlow({ ...base, llmBaseUrl: "https://api.example.com/v1", tts: "elevenlabs", photoCount: 0 });
    expect(f.headline).toBe("Notes → api.example.com; story text → ElevenLabs.");
  });

  it("always says nothing goes to us, and omits photo/notes rows when there are none", () => {
    const f = dataFlow({ ...base, photoCount: 0, hasNotes: false });
    expect(f.rows.map((r) => r.what)).not.toContain("Your notes");
    expect(f.rows.some((r) => r.what.startsWith("Your photos"))).toBe(false);
    expect(f.rows.at(-1)?.where).toMatch(/no server of ours/i);
  });
});

